<?php

namespace App\Http\Requests\Api\V1;

use App\Enums\PunchDirection;
use App\Services\Attendance\Face\Data\FaceSample;
use App\Services\Attendance\Mobile\CheckInData;
use Carbon\CarbonImmutable;
use Illuminate\Foundation\Http\FormRequest;

/**
 * POST /api/v1/me/attendance/check-in | check-out (JSON).
 *
 *   request_uuid        uuid, generated by the app per tap (retries reuse it: idempotent)
 *   latitude, longitude decimal degrees
 *   accuracy            metres (horizontal accuracy reported by the OS)
 *   is_mock_location    bool, the OS / app mock-location indicator
 *   device_time         ISO-8601 with offset, the phone clock at capture
 *   device_id, platform (android|ios), app_version
 *   face                {token?, images?: [base64], liveness_passed?, liveness_score?}
 */
class MobileAttendanceRequest extends FormRequest
{
    public function authorize(): bool
    {
        return $this->user()?->employee_id !== null;
    }

    /**
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        return [
            'request_uuid' => ['required', 'uuid'],
            'latitude' => ['required', 'numeric', 'between:-90,90'],
            'longitude' => ['required', 'numeric', 'between:-180,180'],
            'accuracy' => ['required', 'numeric', 'min:0', 'max:100000'],
            'is_mock_location' => ['sometimes', 'boolean'],
            'device_time' => ['nullable', 'date'],
            'device_id' => ['nullable', 'string', 'max:191'],
            'platform' => ['nullable', 'in:android,ios'],
            'app_version' => ['nullable', 'string', 'max:30'],
            'face' => ['nullable', 'array'],
            'face.token' => ['nullable', 'string', 'max:4096'],
            'face.images' => ['nullable', 'array', 'max:'.config('face_verification.max_images')],
            'face.images.*' => ['string', 'max:'.(int) (config('face_verification.max_image_kb') * 1400)],
            'face.liveness_passed' => ['nullable', 'boolean'],
            'face.liveness_score' => ['nullable', 'numeric', 'between:0,1'],
        ];
    }

    public function toData(PunchDirection $direction): CheckInData
    {
        return new CheckInData(
            $this->string('request_uuid')->lower()->value(),
            $direction,
            (float) $this->input('latitude'),
            (float) $this->input('longitude'),
            (float) $this->input('accuracy'),
            $this->boolean('is_mock_location'),
            $this->filled('device_time') ? CarbonImmutable::parse($this->input('device_time')) : null,
            $this->input('device_id'),
            $this->input('platform'),
            $this->input('app_version'),
            self::faceSample($this->input('face')),
            $this->ip(),
        );
    }

    /**
     * @param  array<string, mixed>|null  $face
     */
    public static function faceSample(?array $face): ?FaceSample
    {
        if ($face === null) {
            return null;
        }

        return new FaceSample(
            isset($face['token']) ? (string) $face['token'] : null,
            array_values(array_filter(array_map(fn ($image) => base64_decode((string) $image, true) ?: null, $face['images'] ?? []))),
            isset($face['liveness_passed']) ? filter_var($face['liveness_passed'], FILTER_VALIDATE_BOOL) : null,
            isset($face['liveness_score']) ? (float) $face['liveness_score'] : null,
        );
    }

    /**
     * @return array<string, string>
     */
    public function attributes(): array
    {
        return trans('mobile.api.fields');
    }
}
